==================================================================

A fork of [node-green-light](https://github.com/axkibe/node-green-light) with parallel execution support.

A sample program in pure node, using the async library, and using asyncblock + fibers.

### Pure node

```javascript

function example(callback){
    var finishedCount = 0;
    var fileContents = [];

    var continuation = function(){
        if(finishedCount < 2){
            return;
        }

        fs.writeFile('path3', fileContents[0], function(err) {
            if(err) {
                throw new Error(err);
            }

            fs.readFile('path3', 'utf8', function(err, data){ 
                console.log(data);
                console.log('all done');
            });
        });
    };

    fs.readFile('path1', 'utf8', function(err, data) {
        if(err) {
            throw new Error(err);
        }

        fnishedCount++;
        fileContents[0] = data;

        continuation();
    });

    fs.readFile('path2', 'utf8', function(err, data) {
        if(err) {
            throw new Error(err);
        }

        fnishedCount++;
        fileContents[1] = data;

        continuation();
    });
}
```

### Using async

```javascript

var async = require('async');

var fileContents = [];

async.series([
    function(callback){
        async.parallel([
            function(callback) {
                fs.readFile('path1', 'utf8', callback);
            },

            function(callback) {
                fs.readFile('path2', 'utf8', callback);
            }
        ],
            function(err, results){
                fileContents = results;                                    
                callback(err);
            }
        );
    },

    function(callback) {
        fs.writeFile('path3', fileContents[0], callback);
    },

    function(callback) {
        fs.readFile('path3', 'utf8', function(err, data){
            console.log(data);
            callback(err);
        });
    }
],
    function(err) {
        if(err) {
            throw new Error(err);
        }

        console.log('all done');
    }
);
```

### Using asyncblock + fibers

```javascript

var asyncblock = require('asyncblock');

asyncblock(function(flow){
    fs.readFile('path1', 'utf8', flow.add('first'));
    fs.readFile('path2', 'utf8', flow.add('second'));

    var fileContents = flow.wait();

    fs.writeFile('path3', fileContents.first, flow.add());
    flow.wait();

    fs.readFile('path3', 'utf8', flow.add());
    var data = flow.wait();

    console.log(data);
    console.log('all done');
});
```

## Notes

### flow.add and flow.wait

Pass the result of flow.add() as a callback to asynchronous functions. Each usage of flow.add() will run in parallel.
Call flow.wait() when you want execution to pause until all the asynchronous functions are done.

You may pass a key to flow.add, which will be used when getting the result from flow.wait. For example, calling
flow.add('key1') and flow.add('key2') would produce a result { key1: value1, key2: value2 }. It is not necessary to
pass a key to flow.add if you do not need to get the result.

If there is only one call to flow.add and no key is passed, the result will be returned as is without the object wrapper.

If any of the asynchronous callbacks pass an error as the first argument, it will be thrown as an exception by asyncblock.
You only receive from the 2nd arg on from the flow.wait call. If more than one parameter was passed to the callback,
it will be returned as an array.

attache.js.readme:
Attache.js
==========
### Javascript implementation of Aspect Oriented Programming paradigm, enclosed in Node.js module

#### How to use:

	var attache = require('attache.js');

	attache.after(some_object, "some_object_function", function() {
		// Code which will be executed _after_ some.object.some_function() call	
	});

	attache.once_after(some_object, "some_object_function", function() {
		// Code which will be executed _only once_ after some.object.some_function() call	
	});

	// Removing aspect function
	// Note: basically, we need to have stored aspect function in the value to pass it properly to remove function
	attache.remove_after(some_object, some_object_function, aspect_function);

	attache.before(some_object, "some_object_function", function() {
		// Code which will be executed _before_ some.object.some_function() call	
	});

	attache.once_before(some_object, "some_object_function", function() {
		// Code which will be executed _only once_ before some.object.some_function() call	
	});

	// Removing aspect function
	// Note: basically, we need to have stored aspect function in the value to pass it properly to remove function
	attache.remove_before(some_object, "some_object_function", aspect_function);


### Example:
	attache = require('attache.js');

	var obj = {
	  test: function(x) { return x; }
	};

	var fake = function() {
	  var fake_val = 100;
	  attache.before(obj, "test", function() {
	  	console.log(fake_val);
		console.log(arguments);    
	  });
	}

	fake();
	console.log(obj.test(2, 3, 4));

##### Output:

	100
	{ '0': 2, '1': 3, '2': 4 }
	2

