      //   {
      //     "is_deleted": true,
      //     "revision": 4,
      //     "rev": "40000000d",
      //     "thumb_exists": false,
      //     "bytes": 0,
      //     "modified": "Wed, 20 Jul 2011 22:41:09 +0000",
      //     "path": "foo/hello.txt",
      //     "is_dir": false,
      //     "icon": "page_white",
      //     "root": "sandbox",
      //     "mime_type": "text/plain",
      //     "size": "0 bytes"
      //   },
      //   {
      //     "revision": 1,
      //     "rev": "10000000d",
      //     "thumb_exists": false,
      //     "bytes": 3,
