### Old Way

```javascript
var fs = require('fs');

fs.stat('some/file.js', function(err, result) {

	if(err) {
		//do stuff
		return;
	}


	//do success stuff
});

```

### Result.js way lets you pick your own flavor

```javascript
var result = require('result');

result.call(fs.stat).on({
	error: function(error) {
		//do error stuff
	},
	data: function(arg, anotherArg) {
		//do everything else
	}
});
```

Another variation

```javascript
var result = require('result');

fs.stat(result({
	error: function(error) {

	},
	result: function(arg) {

	}
}));
````

Just one more....

```javascript
var result = require('result');

fs.stat(result({
	error: result.throwError,
	result: function(arg) {

	}
}));
```

By default, all errors are thrown unless you listen for an unhandled exception, like so:

```javascript

result.on('unhandledError', function() {
	//report bugs here...
});


fs.stat(result(function(result) {

}));
```

